<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>资源管理</h1><p>统一查看课程资源、发布状态和下发任务。</p></div><el-button type="primary" icon="el-icon-reading" @click="$router.push('/management/courses')">进入课程管理</el-button></header><el-tabs v-model="tab"><el-tab-pane label="资源目录" name="resources"><div class="module-table-wrap"><el-table v-loading="loading" :data="rows" empty-text="暂无资源"><el-table-column prop="name" label="资源名称" min-width="220" /><el-table-column prop="resourceType" label="类型" width="120" /><el-table-column prop="courseName" label="所属课程" min-width="180" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="s.row.enabled?'success':'info'">{{ s.row.enabled?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="280" align="right"><template slot-scope="s"><el-button size="small" @click="toggle(s.row)">{{ s.row.enabled?'停用资源':'启用资源' }}</el-button><el-button size="small" :disabled="!s.row.enabled" @click="deliverAll(s.row)">下发到全部环境</el-button></template></el-table-column></el-table></div></el-tab-pane><el-tab-pane label="下发记录" name="deliveries"><div class="module-table-wrap"><el-table v-loading="deliveryLoading" :data="deliveries" empty-text="暂无下发记录"><el-table-column prop="resourceId" label="资源" min-width="180" /><el-table-column prop="userId" label="用户" width="80" /><el-table-column prop="environmentId" label="环境" min-width="180" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="deliveryType(s.row.state)">{{ deliveryText(s.row.state) }}</el-tag></template></el-table-column><el-table-column prop="failureMessage" label="失败原因" min-width="180" show-overflow-tooltip /></el-table></div></el-tab-pane></el-tabs></section></template>
<script>
import { listAdminCourses, listAdminCourseDeliveries, setCourseResourceEnabled, deliverCourseResourceToAll } from '@/api/Courses'
export default { data:()=>({tab:'resources',loading:false,deliveryLoading:false,rows:[],deliveries:[]}), created(){this.load();this.loadDeliveries()}, methods:{async load(){this.loading=true;try{const r=await listAdminCourses();this.rows=(r.data||[]).reduce((all,item)=>all.concat((item.resources||[]).map(resource=>Object.assign({},resource,{courseName:item.course.name}))),[])}finally{this.loading=false}},async loadDeliveries(){this.deliveryLoading=true;try{const r=await listAdminCourseDeliveries();this.deliveries=r.data||[]}finally{this.deliveryLoading=false}},async toggle(row){await setCourseResourceEnabled(row.resourceId,!row.enabled);await this.load()},async deliverAll(row){try{await this.$confirm(`将把“${row.name}”发送到全部用户环境，是否继续？`,'确认下发',{type:'warning'});await deliverCourseResourceToAll(row.resourceId);await this.loadDeliveries();this.tab='deliveries'}catch(e){}},deliveryText(s){return({PENDING:'排队中',DISPATCHED:'已提交',RUNNING:'执行中',SUCCEEDED:'已完成',FAILED:'失败'})[s]||'未知'},deliveryType(s){return s==='SUCCEEDED'?'success':s==='FAILED'?'danger':s?'warning':'info'}}}
</script>
